<template><article v-if="article" class="article-detail"><header><div class="narrow"><div class="breadcrumb"><RouterLink to="/">首页</RouterLink><span>/</span><RouterLink to="/articles">口腔科普</RouterLink></div><p class="eyebrow">ORAL HEALTH GUIDE</p><h1>{{article.title}}</h1><div class="article-meta"><span>{{article.author || settings?.wechatName}}</span><time>{{formatDate(article.publishedAt)}}</time><span>内容来源：微信公众号</span></div></div></header><div class="narrow article-layout"><div v-if="article.digest" class="article-digest">{{article.digest}}</div><div class="wechat-content" v-html="article.contentHtml"></div><div class="article-disclaimer"><strong>温馨提示</strong><p>本文用于口腔健康知识普及，不能替代医生面诊。具体诊断与治疗方案请由专业医生结合检查结果制定。</p></div><a v-if="article.originalUrl" :href="article.originalUrl" target="_blank" rel="noopener noreferrer" class="original-link">在微信公众号查看原文</a></div></article><div v-else class="state-card container">{{error || '正在加载文章…'}}</div></template>
<script setup lang="ts">import { ref,watch } from 'vue';import { RouterLink,useRoute } from 'vue-router';import { Article,websiteApi } from '../api';import { formatDate,setSeo,useSite } from '../site';const route=useRoute();const article=ref<Article|null>(null),error=ref('');const {settings}=useSite();async function load(){article.value=null;error.value='';try{article.value=await websiteApi.article(String(route.params.slug));setSeo(`${article.value.title}｜重庆种博士口腔`,article.value.digest);}catch(e){error.value=e instanceof Error?e.message:'文章加载失败';}}watch(()=>route.params.slug,load,{immediate:true});</script>
